package gal.rodrigosambade.biometriclab;
import android.os.Bundle;import android.security.keystore.*;import android.util.Base64;import android.widget.*;import androidx.annotation.NonNull;import androidx.appcompat.app.AppCompatActivity;import androidx.biometric.BiometricManager;import androidx.biometric.BiometricPrompt;import androidx.core.content.ContextCompat;import java.security.KeyStore;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
public class MainActivity extends AppCompatActivity{
 static final String ALIAS="demo-biometric-aes";EditText input;TextView status;android.content.SharedPreferences prefs;
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);input=findViewById(R.id.input);status=findViewById(R.id.status);prefs=getSharedPreferences("crypto",MODE_PRIVATE);findViewById(R.id.encrypt).setOnClickListener(v->encrypt());findViewById(R.id.decrypt).setOnClickListener(v->decrypt());findViewById(R.id.reset).setOnClickListener(v->reset());showCapability();}
 void showCapability(){int r=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG);status.setText(r==BiometricManager.BIOMETRIC_SUCCESS?"Biometría fuerte disponible":"Biometría no preparada: "+r);}
 SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setUserAuthenticationRequired(true).setUserAuthenticationParameters(0,KeyProperties.AUTH_BIOMETRIC_STRONG).setInvalidatedByBiometricEnrollment(true).build());g.generateKey();}return ((KeyStore.SecretKeyEntry)ks.getEntry(ALIAS,null)).getSecretKey();}
 void encrypt(){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());prompt("Autoriza el cifrado",c,crypto->{try{byte[] out=crypto.getCipher().doFinal(input.getText().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));prefs.edit().putString("iv",Base64.encodeToString(crypto.getCipher().getIV(),Base64.NO_WRAP)).putString("data",Base64.encodeToString(out,Base64.NO_WRAP)).apply();status.setText("Cifrado guardado. La clave no sale del Keystore.");}catch(Exception e){status.setText(e.toString());}});}catch(Exception e){status.setText(e.toString());}}
 void decrypt(){String iv=prefs.getString("iv",null),data=prefs.getString("data",null);if(iv==null||data==null){status.setText("Primero cifra un texto");return;}try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(iv,Base64.NO_WRAP)));prompt("Autoriza el descifrado",c,crypto->{try{byte[] plain=crypto.getCipher().doFinal(Base64.decode(data,Base64.NO_WRAP));status.setText("Texto: "+new String(plain,java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){status.setText(e.toString());}});}catch(Exception e){status.setText(e.toString());}}
 interface CryptoSuccess{void run(BiometricPrompt.CryptoObject c);}void prompt(String title,Cipher c,CryptoSuccess ok){BiometricPrompt p=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(@NonNull BiometricPrompt.AuthenticationResult r){BiometricPrompt.CryptoObject o=r.getCryptoObject();if(o!=null)ok.run(o);}public void onAuthenticationError(int code,@NonNull CharSequence msg){status.setText("Error biométrico: "+msg);}});BiometricPrompt.PromptInfo info=new BiometricPrompt.PromptInfo.Builder().setTitle(title).setSubtitle("Clave AES/GCM protegida por Android Keystore").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG).setNegativeButtonText("Cancelar").build();p.authenticate(info,new BiometricPrompt.CryptoObject(c));}
 void reset(){try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);ks.deleteEntry(ALIAS);prefs.edit().clear().apply();status.setText("Clave y ciphertext eliminados");}catch(Exception e){status.setText(e.toString());}}
}
